style.css:
@-moz-document domain("gemini.google.com") {
/* 1. Global width variable overrides */
:root,
chat-app,
body {
  --chat-max-width: 75vw !important;
  --conversation-max-width: 75vw !important;
  --gemini-chat-max-width: 75vw !important;
  --bottom-container-max-width: 75vw !important;
}

/* 2. Target only the inner message lanes and input container */
.conversation-container,
.bottom-container,
.input-area,
.chat-input-container,
user-query,
model-response {
  max-width: 75vw !important;
  width: 100% !important;
  margin-inline: auto !important;
}

/* 3. Expand tables fully inside the widened messages */
table,
.markdown table,
table-block,
.table-container {
  width: 100% !important;
  max-width: 100% !important;
  table-layout: auto !important;
  overflow-x: visible !important;
}

th,
td {
  white-space: normal !important;
  min-width: fit-content !important;
}
}
